fn remove_duplicates(numbers: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    for number in numbers {
        if seen.insert(number) {
            result.push(number);
        }
    }
    result
}

