fn simple_linear_regression(x: &[f64], y: &[f64]) -> Option<(f64, f64)> {
    let n = x.len();
    if n < 2 || n != y.len() {
        return None;
    }

    let sum_x = x.iter().try_fold(0.0, |acc, &val| Some(acc + val))?;
    let sum_y = y.iter().try_fold(0.0, |acc, &val| Some(acc + val))?;
    let sum_xy = x.iter().zip(y.iter()).try_fold(0.0, |acc, (&xi, &yi)| Some(acc + xi * yi))?;
    let sum_x2 = x.iter().try_fold(0.0, |acc, &val| Some(acc + val * val))?;

    let n_f64 = n as f64;
    let numerator_m = n_f64 * sum_xy - sum_x * sum_y;
    let denominator_m = n_f64 * sum_x2 - sum_x * sum_x;

    if denominator_m.abs() < f64::EPSILON {
        return None; // Avoid division by zero or very small number
    }

    let m = numerator_m / denominator_m;
    let b = (sum_y - m * sum_x) / n_f64;

    Some((m, b))
}

