use chrono::{NaiveDate, Weekday, Duration};

fn count_business_days(start_date_str: &str, end_date_str: &str) -> Result<u32, Box<dyn std::error::Error>> {
    let start_date = NaiveDate::parse_from_str(start_date_str, "%Y-%m-%d")?;
    let end_date = NaiveDate::parse_from_str(end_date_str, "%Y-%m-%d")?;

    if start_date >= end_date {
        return Ok(0);
    }

    let mut business_days_count = 0;
    let mut current_date = start_date;

    while current_date < end_date {
        match current_date.weekday() {
            Weekday::Mon | Weekday::Tue | Weekday::Wed | Weekday::Thu | Weekday::Fri => {
                business_days_count += 1;
            }
            _ => {}
        }
        current_date = current_date.checked_add_signed(Duration::days(1)).ok_or("Date overflow")?;
    }

    Ok(business_days_count)
}

