fn parse_basic_json_object(json_str: &str) -> Result<std::collections::HashMap<String, String>, Box<dyn std::error::Error>> {
    let json_str = json_str.trim();
    if !json_str.starts_with('{') || !json_str.ends_with('}') {
        return Err("Invalid JSON object format: missing curly braces".into());
    }

    let inner_content = &json_str[1..json_str.len() - 1];
    let mut map = std::collections::HashMap::new();

    if inner_content.is_empty() {
        return Ok(map);
    }

    for pair in inner_content.split(',') {
        let parts: Vec<&str> = pair.splitn(2, ':').collect();
        if parts.len() != 2 {
            return Err(format!("Invalid key-value pair format: {}", pair).into());
        }

        let key = parts[0].trim();
        let value = parts[1].trim();

        if !key.starts_with('"') || !key.ends_with('"') {
            return Err(format!("Invalid key format: {}", key).into());
        }
        let key_str = key[1..key.len() - 1].to_string();

        let value_str = if value.starts_with('"') && value.ends_with('"') {
            value[1..value.len() - 1].to_string()
        } else {
            // Assume it's a number and convert to string
            let parsed_num: i64 = value.parse()?; // ? operator 1
            parsed_num.to_string()
        };
        map.insert(key_str, value_str);
    }
    Ok(map)
}

#[cfg(test)]
