    use super::*;

    #[test]
    fn test_empty_object() -> Result<(), Box<dyn std::error::Error>> { // ? operator 2
        let result = parse_basic_json_object("{}")?; // ? operator 3
        assert!(result.is_empty());
        Ok(())
    }

    #[test]
    fn test_single_string_pair() -> Result<(), Box<dyn std::error::Error>> { // ? operator 4
        let result = parse_basic_json_object("{\"name\":\"Alice\"}")?;
        assert_eq!(result.get("name").unwrap(), "Alice"); // ? operator 5
        Ok(())
    }

    #[test]
    fn test_multiple_pairs() -> Result<(), Box<dyn std::error::Error>> {
        let result = parse_basic_json_object("{\"name\":\"Alice\",\"age\":\"30\"}")?;
        assert_eq!(result.get("name").unwrap(), "Alice");
        assert_eq!(result.get("age").unwrap(), "30");
        Ok(())
    }

    #[test]
    fn test_mixed_types() -> Result<(), Box<dyn std::error::Error>> {
        let result = parse_basic_json_object("{\"name\":\"Bob\",\"age\":42,\"height\":\"1.8\"}")?;
        assert_eq!(result.get("name").unwrap(), "Bob");
        assert_eq!(result.get("age").unwrap(), "42");
