        let parts: Vec<&str> = pair.splitn(2, ':').collect();
        if parts.len() != 2 {
            return Err(format!("Invalid key-value pair format: {}", pair).into());
        }

        let key = parts[0].trim();
        let value = parts[1].trim();

        if !key.starts_with('"') || !key.ends_with('"') {
            return Err(format!("Invalid key format: {}", key).into());
        }
        let key_str = key[1..key.len() - 1].to_string();

        let value_str = if value.starts_with('"') && value.ends_with('"') {
            value[1..value.len() - 1].to_string()
        } else {
            // Assume it's a number and convert to string
            let parsed_num: i64 = match value.parse() { Ok(v) => v, Err(e) => return Err(e.into()), }; // ? operator 1
            parsed_num.to_string()
        };
        map.insert(key_str, value_str);
    }
    Ok(map)
}

