use std::io::{self, BufRead};

fn distance(p1: (f64, f64), p2: (f64, f64)) -> f64 {
    let dx = p1.0 - p2.0;
    let dy = p1.1 - p2.1;
    (dx * dx + dy * dy).sqrt()
}

fn polygon_perimeter(vertices: &[(f64, f64)]) -> f64 {
    let mut perimeter = 0.0;
    for i in 0..vertices.len() {
        let p1 = vertices[i];
        let p2 = vertices[(i + 1) % vertices.len()];
        perimeter += distance(p1, p2);
    }
    perimeter
}

fn parse_point(s: &str) -> io::Result<(f64, f64)> {
    let parts: Vec<&str> = s.split(',').collect();
    if parts.len() != 2 {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "Invalid point format"));
    }
    let x = parts[0].trim().parse::<f64>().map_err(|e| io::Error::new(io::ErrorKind::InvalidData, format!("Invalid x coordinate: {}", e)))?;
    let y = parts[1].trim().parse::<f64>().map_err(|e| io::Error::new(io::ErrorKind::InvalidData, format!("Invalid y coordinate: {}", e)))?;
    Ok((x, y))
}

fn read_polygon_from_stdin() -> io::Result<Vec<(f64, f64)>> {
    let stdin = io::stdin();
    let mut handle = stdin.lock();
    let mut line = String::new();
    handle.read_line(&mut line)?;
    let points_str = line.trim();

    let point_strs: Vec<&str> = points_str.split(';').collect();
    if point_strs.len() < 2 {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "At least two points are required"));
    }

    let mut vertices = Vec::new();
    for ps in point_strs {
        let point = parse_point(ps)?;
        vertices.push(point);
    }
    Ok(vertices)
}

fn main() -> io::Result<()> {
    let vertices = read_polygon_from_stdin()?;
    let perimeter = polygon_perimeter(&vertices);
    println!("{:.2}", perimeter);
    Ok(())
}

