fn hex_to_rgb(hex_color: &str) -> Option<(u8, u8, u8)> {
    if !hex_color.starts_with('#') || hex_color.len() != 7 {
        return None;
    }

    let hex_slice = &hex_color[1..];

    let r_str = hex_slice.get(0..2)?;
    let g_str = hex_slice.get(2..4)?;
    let b_str = hex_slice.get(4..6)?;

    let r = u8::from_str_radix(r_str, 16).ok()?;
    let g = u8::from_str_radix(g_str, 16).ok()?;
    let b = u8::from_str_radix(b_str, 16).ok()?;

    Some((r, g, b))
}

