fn contains_substring(text: &str, pattern: &str) -> bool {
    let mut text_chars = text.chars().peekable();
    let mut pattern_chars = pattern.chars().peekable();

    if pattern_chars.peek().is_none() {
        return true; // Empty pattern is always found
    }

    while let Some(t_char) = text_chars.next() {
        if t_char == *pattern_chars.peek().unwrap() { // ?
            let mut temp_text_chars = Some(t_char).into_iter().chain(text_chars.clone()).peekable(); // ?
            let mut temp_pattern_chars = pattern_chars.clone();

            let mut match_found = true;
            while let Some(p_char) = temp_pattern_chars.next() {
                if let Some(tt_char) = temp_text_chars.next() { // ?
                    if tt_char != p_char {
                        match_found = false;
                        break;
                    }
                } else {
                    match_found = false;
                    break;
                }
            }
            if match_found {
                return true;
            }
        }
    }
    false
}

