    let mut pattern_chars = pattern.chars().peekable();

    if pattern_chars.peek().is_none() {
        return true; // Empty pattern is always found
    }

    while let Some(t_char) = text_chars.next() {
        if t_char == match pattern_chars.peek() {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        } {
            let mut temp_text_chars = match Some(t_char).into_iter().chain(text_chars.clone()).peekable() {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            };
            let mut temp_pattern_chars = pattern_chars.clone();

            let mut match_found = true;
            while let Some(p_char) = temp_pattern_chars.next() {
                if let Some(tt_char) = match temp_text_chars.next() {
                    Ok(v) => v,
                    Err(e) => return Err(e.into()),
                } {
                    if tt_char != p_char {
                        match_found = false;
                        break;
                    }
                } else {
                    match_found = false;
                    break;
                }
            }
            if match_found {
                return true;
            }
        }
    }
    false
}

