use std::collections::HashMap;

fn parse_key_value_string(input: &str) -> Result<HashMap<String, String>, Box<dyn std::error::Error>> {
    let mut map = HashMap::new();

    if input.is_empty() {
        return Ok(map);
    }

    for pair_str in input.split(',') {
        let mut parts = pair_str.split(':');
        let key_option = parts.next();
        let value_option = parts.next();

        let key = key_option.ok_or("Missing key in pair")?.to_string();
        let value = value_option.ok_or("Missing value in pair")?.to_string();

        if parts.next().is_some() {
            return Err("Too many colons in pair".into());
        }

        map.insert(key, value);
    }
    Ok(map)
}

