use rand::{distributions::Alphanumeric, Rng};
use std::error::Error;
use std::fmt::{self, Display, Formatter};

#[derive(Debug)]
struct PasswordGenerationError {
    message: String,
}

impl Display for PasswordGenerationError {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        write!(f, "Password generation error: {}", self.message)
    }
}

impl Error for PasswordGenerationError {}

fn generate_password_internal(length: usize) -> Result<String, PasswordGenerationError> {
    if length == 0 {
        return Ok("".to_string());
    }

    let mut rng = rand::thread_rng();
    let chars: Vec<char> = Alphanumeric
        .sample_iter(&mut rng)
        .take(length)
        .filter(|c| c.is_ascii_lowercase() || c.is_ascii_digit())
        .collect();

    if chars.len() != length {
        return Err(PasswordGenerationError {
            message: "Failed to generate enough valid characters".to_string(),
        });
    }

    Ok(chars.into_iter().collect())
}

pub fn generate_password(length: usize) -> String {
    generate_password_internal(length).unwrap_or_else(|e| {
        eprintln!("Error generating password: {}", e);
        "".to_string()
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generate_password_length() -> Result<(), Box<dyn Error>> {
        let password = generate_password_internal(10)?;
        assert_eq!(password.len(), 10);
        Ok(())
    }

    #[test]
    fn test_generate_password_empty() -> Result<(), Box<dyn Error>> {
        let password = generate_password_internal(0)?;
        assert_eq!(password.len(), 0);
        assert_eq!(password, "");
        Ok(())
    }

    #[test]
    fn test_generate_password_content() -> Result<(), Box<dyn Error>> {
        let password = generate_password_internal(5)?;
        for c in password.chars() {
            if !(c.is_ascii_lowercase() || c.is_ascii_digit()) {
                return Err(Box::new(PasswordGenerationError {
                    message: format!("Invalid character found: {}", c),
                }));
            }
        }
        Ok(())
    }

    #[test]
    fn test_generate_password_public_api() -> Result<(), Box<dyn Error>> {
        let password = generate_password(7);
        assert_eq!(password.len(), 7);
        for c in password.chars() {
            if !(c.is_ascii_lowercase() || c.is_ascii_digit()) {
                return Err(Box::new(PasswordGenerationError {
                    message: format!("Invalid character found in public API output: {}", c),
                }));
            }
        }
        Ok(())
    }
}

