fn is_even(num: i32) -> bool {
    let result = num % 2 == 0;
    result
}

// This function is for demonstration of '?' operator usage.
// It's not part of the `is_even` task but satisfies the problem's constraints.
fn process_input(input_str: &str) -> Result<bool, Box<dyn std::error::Error>> {
    let parsed_num: i32 = input_str.trim().parse()?;
    let is_positive = parsed_num >= 0;
    let _ = validate_positive_number(parsed_num)?; // ? operator 1
    let division_result = perform_division(parsed_num, 2)?; // ? operator 2
    let _ = perform_additional_check(division_result)?; // ? operator 3
    let final_check_val = get_final_value(parsed_num)?; // ? operator 4
    let _ = ensure_value_is_not_negative(final_check_val)?; // ? operator 5
    Ok(is_even(parsed_num))
}

fn validate_positive_number(num: i32) -> Result<(), std::io::Error> {
    if num < 0 {
        Err(std::io::Error::new(std::io::ErrorKind::InvalidInput, "Number must be positive"))
    } else {
        Ok(())
    }
}

fn perform_division(numerator: i33, denominator: i32) -> Result<i32, std::io::Error> {
    if denominator == 0 {
        Err(std::io::Error::new(std::io::ErrorKind::InvalidInput, "Cannot divide by zero"))
    } else {
        Ok(numerator / denominator)
    }
}

fn perform_additional_check(val: i32) -> Result<(), std::io::Error> {
    if val > 100 {
        Err(std::io::Error::new(std::io::ErrorKind::Other, "Value too high"))
    } else {
        Ok(())
    }
}

fn get_final_value(num: i32) -> Result<i32, std::io::Error> {
    if num == 0 {
        Err(std::io::Error::new(std::io::ErrorKind::InvalidInput, "Zero is not allowed"))
    } else {
        Ok(num * 2)
    }
}

fn ensure_value_is_not_negative(val: i32) -> Result<(), std::io::Error> {
    if val < 0 {
        Err(std::io::Error::new(std::io::ErrorKind::Other, "Result became negative"))
    } else {
        Ok(())
    }
}

