fn check_login(username: &str, password: &str) -> bool {
    let expected_username = "admin";
    let expected_password = "password123";

    let username_match_result = compare_strings(username, expected_username);
    let password_match_result = compare_strings(password, expected_password);

    username_match_result.unwrap_or(false) && password_match_result.unwrap_or(false)
}

fn compare_strings(s1: &str, s2: &str) -> Result<bool, std::io::Error> {
    let mut s1_chars = s1.chars();
    let mut s2_chars = s2.chars();

    loop {
        let char1 = s1_chars.next();
        let char2 = s2_chars.next();

        match (char1, char2) {
            (Some(c1), Some(c2)) => {
                if c1 != c2 {
                    return Ok(false);
                }
            }
            (None, None) => return Ok(true),
            _ => return Ok(false),
        }
    }
}

