fn calculate_age(birth_year: u16, current_year: u16) -> Result<u16, String> {
    if birth_year > current_year {
        return Err("Birth year cannot be after current year.".to_string());
    }
    let age = current_year.checked_sub(birth_year).ok_or_else(|| "Subtraction overflowed.".to_string())?;
    Ok(age)
}

