fn dice_sum_probability(target_sum: u8) -> Result<f64, String> {
    if target_sum < 2 || target_sum > 12 {
        return Err("Target sum must be between 2 and 12 inclusive.".to_string());
    }

    let mut successful_outcomes = 0;
    for die1 in 1..=6 {
        for die2 in 1..=6 {
            let current_sum = die1 + die2;
            if current_sum == target_sum {
                successful_outcomes += 1;
            }
        }
    }

    let total_outcomes = 36;
    Ok(successful_outcomes as f64 / total_outcomes as f64)
}

