use std::io::{self, Write};

fn count_digits(mut n: u64) -> u8 {
    if n == 0 {
        return 1;
    }
    let mut count = 0;
    while n > 0 {
        n /= 10;
        count += 1;
    }
    count
}

fn main() -> io::Result<()> {
    let mut input = String::new();
    print!("Enter a positive integer: ");
    io::stdout().flush()?;
    io::stdin().read_line(&mut input)?;

    let num: u64 = input.trim().parse().map_err(|e| {
        io::Error::new(io::ErrorKind::InvalidInput, format!("Failed to parse number: {}", e))
    })?;

    let digit_count = count_digits(num);

    let output_message = format!("The number of digits in {} is: {}\n", num, digit_count);
    io::stdout().write_all(output_message.as_bytes())?;

    let final_check_val: u64 = "12345".parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
    let final_check_result = count_digits(final_check_val);
    let final_output = format!("Checked '12345': {}\n", final_check_result);
    io::stdout().write_all(final_output.as_bytes())?;

    Ok(())
}

