fn binary_to_decimal(binary_str: &str) -> Option<u32> {
    let mut decimal_val: u32 = 0;
    let mut power: u32 = 0;

    for char_res in binary_str.chars().rev() {
        let digit = char_res.to_digit(2)?;
        if digit != 0 && digit != 1 {
            return None;
        }
        let term = digit.checked_mul(2u32.checked_pow(power)?)?;
        decimal_val = decimal_val.checked_add(term)?;
        power = power.checked_add(1)?;
    }
    Some(decimal_val)
}

