fn is_sorted_ascending(numbers: &[i32]) -> bool {
    if numbers.len() <= 1 {
        return true;
    }

    let mut iter = numbers.iter();
    let mut prev = *iter.next().expect("Slice is not empty");

    while let Some(current) = iter.next() {
        if prev > *current {
            return false;
        }
        prev = *current;
    }
    true
}

