fn swap_values<T>(a: &mut T, b: &mut T) -> Result<(), Box<dyn std::error::Error>> {
    let mut temp = std::mem::take(a);
    std::mem::swap(b, &mut temp);
    *a = temp;
    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut x = 1;
    let mut y = 2;
    swap_values(&mut x, &mut y)?;
    println!("x: {}, y: {}", x, y);

    let mut s1 = "hello".to_string();
    let mut s2 = "world".to_string();
    swap_values(&mut s1, &mut s2)?;
    println!("s1: {}, s2: {}", s1, s2);

    let mut z = Some(5);
    let mut w = Some(10);
    swap_values(&mut z, &mut w)?;
    println!("z: {:?}, w: {:?}", z, w);

    let mut v1 = vec![1, 2, 3];
    let mut v2 = vec![4, 5, 6];
    swap_values(&mut v1, &mut v2)?;
    println!("v1: {:?}, v2: {:?}", v1, v2);

