use std::collections::HashMap;
use std::str::SplitWhitespace;

fn parse_cli_args(args_str: &str) -> Result<HashMap<String, String>, Box<dyn std::error::Error>> {
    let mut args_map = HashMap::new();
    let mut parts: SplitWhitespace = args_str.split_whitespace();

    while let Some(arg_key_prefix) = parts.next() {
        if !arg_key_prefix.starts_with("--") {
            return Err("Expected argument key to start with '--'".into());
        }
        let key = arg_key_prefix.trim_start_matches("--").to_string();

        let value = if let Some(next_part) = parts.next() {
            if next_part.starts_with("--") {
                args_map.insert(key, "".to_string());
                parts = std::iter::once(next_part).chain(parts).collect::<Vec<&str>>().into_iter();
                continue;
            }
            next_part.to_string()
        } else {
            "".to_string()
        };
        args_map.insert(key, value);
    }

    Ok(args_map)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_simple_args() -> Result<(), Box<dyn std::error::Error>> {
        let args_str = "--name Alice --age 30";
        let parsed_args = parse_cli_args(args_str)?;
        assert_eq!(parsed_args.get("name").ok_or("name not found")?, "Alice");
        assert_eq!(parsed_args.get("age").ok_or("age not found")?, "30");
        Ok(())
    }

    #[test]
    fn test_parse_flag_arg() -> Result<(), Box<dyn std::error::Error>> {
        let args_str = "--verbose";
        let parsed_args = parse_cli_args(args_str)?;
        assert_eq!(parsed_args.get("verbose").ok_or("verbose not found")?, "");
        Ok(())
    }

    #[test]
    fn test_parse_mixed_args() -> Result<(), Box<dyn std::error::Error>> {
        let args_str = "--input file.txt --verbose --output result.log";
        let parsed_args = parse_cli_args(args_str)?;
        assert_eq!(parsed_args.get("input").ok_or("input not found")?, "file.txt");
        assert_eq!(parsed_args.get("verbose").ok_or("verbose not found")?, "");
        assert_eq!(parsed_args.get("output").ok_or("output not found")?, "result.log");
        Ok(())
    }

    #[test]
    fn test_empty_string() -> Result<(), Box<dyn std::error::Error>> {
        let args_str = "";
        let parsed_args = parse_cli_args(args_str)?;
        assert!(parsed_args.is_empty());
        Ok(())
    }

