fn simulate_word_count(file_content: &str) -> Result<usize, std::io::Error> {
    let mut reader = std::io::BufReader::new(file_content.as_bytes());
    let mut buffer = String::new();
    let mut total_words = 0;

    loop {
        let bytes_read = reader.read_line(&mut buffer)?;
        if bytes_read == 0 {
