fn generate_range(start: i32, end: i32) -> Result<Vec<i32>, String> {
    if start > end {
        return Ok(vec![]);
    }
    let mut result = Vec::new();
    let mut current = start;
    while current <= end {
        result.push(current);
        current = current.checked_add(1).ok_or("Integer overflow during range generation")?;
    }
    Ok(result)
}

