    let range3 = generate_range(0, 0)?;
    println!("{:?}", range3);

    let range4 = generate_range(-3, 2)?;
    println!("{:?}", range4);

    let range5 = generate_range(i32::MAX - 2, i32::MAX)?;
    println!("{:?}", range5);

    Ok(())
}

