use rand::Rng;
use rand::thread_rng;
use std::error::Error;

fn generate_random_int(min: i32, max: i32) -> Result<i32, Box<dyn Error>> {
    if min > max {
        return Err("min cannot be greater than max".into());
    }
    let mut rng = thread_rng();
    let random_value = rng.gen_range(min..=max);
    Ok(random_value)
}

fn main() -> Result<(), Box<dyn Error>> {
    let r1 = generate_random_int(1, 10)?;
    println!("Random between 1 and 10: {}", r1);

    let r2 = generate_random_int(-5, 5)?;
    println!("Random between -5 and 5: {}", r2);

    let r3 = generate_random_int(5, 5)?;
    println!("Random for 5 to 5: {}", r3);

    let r4 = generate_random_int(100, 200)?;
    println!("Random between 100 and 200: {}", r4);

    let r5 = generate_random_int(0, 0)?;
    println!("Random for 0 to 0: {}", r5);

    let r_err = generate_random_int(10, 1);
    match r_err {
        Ok(val) => println!("This should not happen: {}", val),
        Err(e) => println!("Error: {}", e),
    }

    Ok(())
}

