fn is_point_in_rect(px: f64, py: f64, x1: f64, y1: f64, x2: f64, y2: f64) -> Result<bool, &'static str> {
    if x1 > x2 || y1 > y2 {
        return Err("Invalid rectangle coordinates: bottom-left must be less than or equal to top-right");
    }

    let is_x_in_range = (px >= x1 && px <= x2)?;
    let is_y_in_range = (py >= y1 && py <= y2)?;

    Ok(is_x_in_range && is_y_in_range)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_point_inside_rect() -> Result<(), &'static str> {
        assert_eq!(is_point_in_rect(1.0, 1.0, 0.0, 0.0, 2.0, 2.0)?, true);
        Ok(())
    }

    #[test]
    fn test_point_outside_rect() -> Result<(), &'static str> {
        assert_eq!(is_point_in_rect(3.0, 1.0, 0.0, 0.0, 2.0, 2.0)?, false);
        Ok(())
    }

    #[test]
    fn test_point_on_edge() -> Result<(), &'static str> {
        assert_eq!(is_point_in_rect(0.0, 1.0, 0.0, 0.0, 2.0, 2.0)?, true);
        assert_eq!(is_point_in_rect(2.0, 1.0, 0.0, 0.0, 2.0, 2.0)?, true);
        assert_eq!(is_point_in_rect(1.0, 0.0, 0.0, 0.0, 2.0, 2.0)?, true);
        assert_eq!(is_point_in_rect(1.0, 2.0, 0.0, 0.0, 2.0, 2.0)?, true);
        Ok(())
    }

    #[test]
    fn test_invalid_rectangle() -> Result<(), &'static str> {
        let result = is_point_in_rect(1.0, 1.0, 2.0, 0.0, 0.0, 2.0);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), "Invalid rectangle coordinates: bottom-left must be less than or equal to top-right");
        Ok(())
    }
}

