use std::io::{self, BufRead};

fn grep_lines(lines: &Vec<String>, pattern: &str) -> io::Result<Vec<String>> {
    let mut matching_lines: Vec<String> = Vec::new();
    for line in lines {
        if line.contains(pattern) {
            matching_lines.push(line.clone());
        }
    }
    Ok(matching_lines)
}

fn main() -> io::Result<()> {
    let input_lines = vec![
        "Hello, Rust!".to_string(),
        "Learning Rust is fun.".to_string(),
        "I love programming.".to_string(),
        "Rustaceans unite!".to_string(),
    ];

    let search_pattern = "Rust";
    let matches = grep_lines(&input_lines, search_pattern)?; 

    println!("Lines containing '{}':", search_pattern);
    for line in matches {
        println!("{}", line);
    }

    let another_pattern = "fun";
    let more_matches = grep_lines(&input_lines, another_pattern)?; 
    println!("\nLines containing '{}':", another_pattern);
    for line in more_matches {
        println!("{}", line);
    }

    let third_pattern = "programming";
    let final_matches = grep_lines(&input_lines, third_pattern)?;
    if final_matches.is_empty() {
        println!("\nNo lines contained '{}'.", third_pattern);
    } else {
        println!("\nLines containing '{}':", third_pattern);
        for line in final_matches {
            println!("{}", line);
        }
    }

    let non_existent_pattern = "nonexistent";
    let no_matches = grep_lines(&input_lines, non_existent_pattern)?; 
    if no_matches.is_empty() {
        println!("\nNo lines contained '{}'.", non_existent_pattern);
    }

    let empty_vec: Vec<String> = Vec::new();
    let result_from_empty = grep_lines(&empty_vec, "anything")?; 
    assert!(result_from_empty.is_empty());

    Ok(())
}

