use std::collections::HashMap;
use std::io::{self, BufRead, BufReader};
use std::fs::File;

fn first_unique_char(s: &str) -> Option<char> {
    let mut counts = HashMap::new();
    for c in s.chars() {
        *counts.entry(c).or_insert(0) += 1;
    }
    for c in s.chars() {
        if *counts.get(&c)? == 1 {
            return Some(c);
        }
    }
    None
}

