    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let mut first_line = String::new();
    reader.lines().next().transpose()?.map(|line| {
        first_line = line;
        first_unique_char(&first_line)
    }).ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, "File is empty").into())
}

