fn sum_even_indexed(v: &Vec<i32>) -> Result<i32, Box<dyn std::error::Error>> {
    let mut sum = 0;
    let mut index = 0;
    while index < v.len() {
        if let Some(val) = v.get(index) {
            sum += val;
        } else {
            return Err("Index out of bounds".into());
        }
        index += 2;
    }
    Ok(sum)
}

