fn filter_by_prefix(strings: &Vec<String>, prefix: &str) -> Result<Vec<String>, String> {
    let mut filtered_strings = Vec::new();
    for s in strings {
        if s.starts_with(prefix) {
            filtered_strings.push(s.clone());
        }
    }
    Ok(filtered_strings)
}

fn process_and_filter(data: &str, prefix: &str) -> Result<Vec<String>, String> {
    let lines: Vec<String> = data.lines().map(|s| s.to_string()).collect();
    let filtered = filter_by_prefix(&lines, prefix)?;
    Ok(filtered)
}

fn main() -> Result<(), String> {
    let input_data = "apple\napricot\nbanana\n";
    let prefix = "ap";
    let result = process_and_filter(input_data, prefix)?;
    if result != vec!["apple".to_string(), "apricot".to_string()] {
        return Err("Unexpected result for basic filtering".to_string());
    }

    let empty_data = "";
    let empty_result = process_and_filter(empty_data, prefix)?;
    if !empty_result.is_empty() {
        return Err("Filtering empty data failed".to_string());
    }

    let no_match_data = "cat\ndog";
    let no_match_prefix = "z";
    let no_match_result = process_and_filter(no_match_data, no_match_prefix)?;
    if !no_match_result.is_empty() {
        return Err("Filtering with no matches failed".to_string());
    }

    let case_sensitive_data = "Hello\nhello";
    let case_sensitive_prefix = "hello";
    let case_sensitive_result = process_and_filter(case_sensitive_data, case_sensitive_prefix)?;
    if case_sensitive_result != vec!["hello".to_string()] {
        return Err("Case-sensitive filtering failed".to_string());
    }

    let complex_data = "apple pie\napply now\nbanana split";
    let complex_prefix = "app";
    let complex_result = process_and_filter(complex_data, complex_prefix)?;
    if complex_result != vec!["apple pie".to_string(), "apply now".to_string()] {
        return Err("Complex filtering failed".to_string());
    }

    println!("All tests passed!");
    Ok(())
}

