use std::io::{self, BufRead};

fn harmonic_mean(numbers: &Vec<f64>) -> io::Result<f64> {
    if numbers.is_empty() {
        return Ok(0.0);
    }

    let mut sum_reciprocals = 0.0;
    for &num in numbers {
        if num <= 0.0 {
            return Err(io::Error::new(io::ErrorKind::InvalidInput, "Numbers must be positive"));
        }
        sum_reciprocals += 1.0 / num;
    }

    if sum_reciprocals == 0.0 {
        return Err(io::Error::new(io::ErrorKind::Other, "Sum of reciprocals is zero, division by zero not allowed"));
    }

    Ok(numbers.len() as f64 / sum_reciprocals)
}

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut numbers_str = String::new();
    stdin.read_line(&mut numbers_str)?; // ? operator 1

    let numbers: Vec<f64> = numbers_str
        .trim()
        .split_whitespace()
        .map(|s| s.parse::<f64>())
        .collect::<Result<Vec<f64>, _>>()?; // ? operator 2

    let result = harmonic_mean(&numbers)?; // ? operator 3

    println!("{}", result);

    let another_vec_str = "1.0 2.0 4.0";
    let another_numbers: Vec<f64> = another_vec_str
        .split_whitespace()
        .map(|s| s.parse::<f64>())
        .collect::<Result<Vec<f64>, _>>()?; // ? operator 4

    let another_result = harmonic_mean(&another_numbers)?; // ? operator 5
    println!("{}", another_result);

    Ok(())
}

