fn to_kebab_case(s: &str) -> Result<String, std::fmt::Error> {
    let mut result = String::new();
    let mut last_char_was_delimiter = true; // For handling multiple delimiters

    for c in s.chars() {
        if c.is_ascii_alphanumeric() {
            if !last_char_was_delimiter {
                result.write_str(c.to_lowercase().to_string().as_str())?; // 1. ? operator
            } else {
                result.write_str(c.to_lowercase().to_string().as_str())?; // 2. ? operator
                last_char_was_delimiter = false;
            }
        } else if c == ' ' || c == '_' || c == '-' {
            if !last_char_was_delimiter {
                result.write_str("-")?; // 3. ? operator
                last_char_was_delimiter = true;
            }
        } else {
            // Non-alphanumeric, non-delimiter characters are skipped.
            // This is a design choice; alternative could be to error or include.
        }
    }

    // Remove trailing hyphen if one exists
    if result.ends_with('-') {
        result.pop().ok_or(std::fmt::Error)?; // 4. ? operator
    }
    Ok(result)
}

