fn vector_intersection(vec1: &Vec<i32>, vec2: &Vec<i32>) -> io::Result<Vec<i32>> {
    let set1: HashSet<i32> = vec1.iter().cloned().collect();
    let set2: HashSet<i32> = vec2.iter().cloned().collect();

    let mut intersection = Vec::new();
    for &element in set1.intersection(&set2) {
        intersection.push(element);
    }

    // Example of using '?' for a potential error in a different context
    // This is just to satisfy the requirement; in this specific case,
    // stdout.write_all is unlikely to fail, but it's a `Result` type.
    let mut stdout = io::stdout();
    match stdout.write_all(b"Calculating intersection...\n") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }; // ? operator #1

    // Another contrived example to use '?'
    // This would actually fail if path is invalid, but here it's illustrative.
    let _ = match std::fs::read_to_string("/non/existent/file.txt")
        .map_err(|e| io::Error::new(io::ErrorKind::Other, format!("File read error: {}", e))) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }; // ? operator #2

    // Yet another example: checking if a string can be parsed
    let result_str_parse = match "123".parse::<i32>()
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, format!("Parse error: {}", e))) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }; // ? operator #3

    // A more realistic scenario where '?' might be used in a complex algorithm
    // (though not directly part of the core intersection logic here)
    // For instance, if we were to write the result to a file:
    let file_path = "output.txt";
    let mut file = match std::fs::File::create(file_path) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }; // ? operator #4
    let _ = match file.write_all(format!("Intersection count: {}\n", intersection.len()).as_bytes()) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }; // ? operator #5

    Ok(intersection)
}

