use std::collections::VecDeque;
use std::io::{self, Read};

fn peek_queue(q: &VecDeque<i32>) -> Option<&i32> {
    q.front()
}

fn process_input(input: &mut dyn Read) -> io::Result<Option<i32>> {
    let mut buffer = String::new();
    input.read_to_string(&mut buffer)?;
    let mut parts = buffer.trim().split_whitespace();
    let count_str = parts.next().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "Missing count"))?;
    let count: usize = count_str.parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))?;
    let mut deque = VecDeque::new();
    for _ in 0..count {
        let num_str = parts.next().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "Missing number"))?;
        let num: i32 = num_str.parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))?;
        deque.push_back(num);
    }
    Ok(peek_queue(&deque).copied())
}

