fn remove_first_n_chars(s: &str, n: usize) -> Result<String, std::io::Error> {
    if n >= s.len() {
        return Ok("".to_string());
    }

    let mut result = String::with_capacity(s.len().checked_sub(n).ok_or_else(|| {
        std::io::Error::new(std::io::ErrorKind::Other, "capacity calculation error")
    })?);

    let mut char_indices = s.char_indices();
    let _ = char_indices.nth(n - 1).ok_or_else(|| {
        std::io::Error::new(std::io::ErrorKind::Other, "failed to skip characters")
    })?;

    for (_, c) in char_indices {
        result.push(c);
    }

    Ok(result)
}

fn main() -> Result<(), std::io::Error> {
    let s1 = "hello";
    let n1 = 2;
    let res1 = remove_first_n_chars(s1, n1)?;
    println!("'{}' after removing {} chars: '{}'", s1, n1, res1);

    let s2 = "world";
    let n2 = 5;
    let res2 = remove_first_n_chars(s2, n2)?;
    println!("'{}' after removing {} chars: '{}'", s2, n2, res2);

    let s3 = "test";
    let n3 = 0;
    let res3 = remove_first_n_chars(s3, n3)?;
    println!("'{}' after removing {} chars: '{}'", s3, n3, res3);

    let s4 = "rust";
    let n4 = 6;
    let res4 = remove_first_n_chars(s4, n4)?;
    println!("'{}' after removing {} chars: '{}'", s4, n4, res4);

    Ok(())
}

