fn get_y_coord(val: f64) -> Result<f64, String> { Ok(val) }
fn safe_subtract(a: f64, b: f64) -> Result<f64, String> { Ok(a - b) }
fn safe_divide(numerator: f64, denominator: f64) -> Result<f64, String> {
    if denominator == 0.0 {
        Ok(if numerator > 0.0 { f64::INFINITY } else if numerator < 0.0 { f64::NEG_INFINITY } else { f64::NAN })
    } else {
        Ok(numerator / denominator)
    }
}

