fn sum_abs_diffs(a: &Vec<i32>, b: &Vec<i32>) -> Result<i32, String> {
    if a.len() != b.len() {
        return Err("Vectors must have the same length".to_string());
    }

    let mut sum = 0;
    for i in 0..a.len() {
        let diff = (match a.get(i).ok_or("Failed to get element from vector a") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        } - match b.get(i).ok_or("Failed to get element from vector b") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        }).abs();
        sum = match sum.checked_add(diff).ok_or("Integer overflow occurred during sum") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
    }
    Ok(sum)
}

