fn pop_stack(stack: &mut Vec<i32>) -> Option<i32> {
    stack.pop()
}

fn process_stack_operations(mut stack: Vec<i32>, operations: &[&str]) -> Result<Vec<i32>, String> {
    let mut results = Vec::new();
    for op in operations {
        match *op {
            "pop" => {
                let val = pop_stack(&mut stack).ok_or_else(|| "Stack is empty, cannot pop".to_string())?;
                results.push(val);
            }
            "push" => {
                return Err("Missing value for push operation".to_string());
            }
            _ => {
                let parsed_val: i32 = op.parse().map_err(|e| format!("Invalid number format: {}", e))?;
                stack.push(parsed_val);
            }
        }
    }
    Ok(results)
}

fn demonstrate_pop_stack() -> Result<(), String> {
    let mut s1 = vec![1, 2, 3];
    let p1 = pop_stack(&mut s1).ok_or_else(|| "Unexpected empty stack for s1".to_string())?;
    assert_eq!(p1, 3);
    assert_eq!(s1, vec![1, 2]);

    let mut empty_s = vec![];
    let p2 = pop_stack(&mut empty_s);
    assert_eq!(p2, None);

    let mut s2 = vec![10];
    let p3 = pop_stack(&mut s2).ok_or_else(|| "Unexpected empty stack for s2".to_string())?;
    assert_eq!(p3, 10);
    assert_eq!(s2, vec![]);
    let p4 = pop_stack(&mut s2);
    assert_eq!(p4, None);

    let mut s3 = vec![1, 2];
    let _ = process_stack_operations(s3, &["pop"]).map_err(|e| format!("Operation failed: {}", e))?;
    Ok(())
}

fn main() -> Result<(), String> {
    demonstrate_pop_stack()?;
    println!("All stack operations successful.");
    Ok(())
}

