fn levenshtein_distance(s1: &str, s2: &str) -> Result<usize, Box<dyn std::error::Error>> {
    let s1_chars: Vec<char> = s1.chars().collect();
    let s2_chars: Vec<char> = s2.chars().collect();

    let n = s1_chars.len();
    let m = s2_chars.len();

    if n == 0 {
        return Ok(m);
    }
    if m == 0 {
        return Ok(n);
    }

    let last_s1_char = s1_chars.last().ok_or("s1_chars empty")?;
    let last_s2_char = s2_chars.last().ok_or("s2_chars empty")?;

    let cost = if last_s1_char == last_s2_char { 0 } else { 1 };

    let s1_prefix = s1_chars[..n - 1].iter().collect::<String>();
    let s2_prefix = s2_chars[..m - 1].iter().collect::<String>();

    let delete_cost = levenshtein_distance(&s1_prefix, s2)?;
    let insert_cost = levenshtein_distance(s1, &s2_prefix)?;
    let substitute_cost = levenshtein_distance(&s1_prefix, &s2_prefix)?;

    Ok(
        delete_cost.min(insert_cost).min(substitute_cost + cost)
    )
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("{}", levenshtein_distance("kitten", "sitting")?); // Expected: 3
    println!("{}", levenshtein_distance("flaw", "lawn")?);     // Expected: 2
    println!("{}", levenshtein_distance("abc", "abc")?);       // Expected: 0
    println!("{}", levenshtein_distance("a", "")?);            // Expected: 1
    println!("{}", levenshtein_distance("", "b")?);            // Expected: 1
    Ok(())
}

