fn levenshtein_distance(s1: &str, s2: &str) -> Result<usize, Box<dyn std::error::Error>> {
    let s1_chars: Vec<char> = s1.chars().collect();
    let s2_chars: Vec<char> = s2.chars().collect();

    let n = s1_chars.len();
    let m = s2_chars.len();

    if n == 0 {
        return Ok(m);
    }
    if m == 0 {
        return Ok(n);
    }

    let last_s1_char = match s1_chars.last().ok_or("s1_chars empty") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let last_s2_char = match s2_chars.last().ok_or("s2_chars empty") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    let cost = if last_s1_char == last_s2_char { 0 } else { 1 };

    let s1_prefix = s1_chars[..n - 1].iter().collect::<String>();
    let s2_prefix = s2_chars[..m - 1].iter().collect::<String>();

    let delete_cost = match levenshtein_distance(&s1_prefix, s2) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let insert_cost = match levenshtein_distance(s1, &s2_prefix) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let substitute_cost = match levenshtein_distance(&s1_prefix, &s2_prefix) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    Ok(
        delete_cost.min(insert_cost).min(substitute_cost + cost)
    )
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("{}", match levenshtein_distance("kitten", "sitting") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }); // Expected: 3
    println!("{}", match levenshtein_distance("flaw", "lawn") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });     // Expected: 2
    println!("{}", match levenshtein_distance("abc", "abc") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });       // Expected: 0
    println!("{}", match levenshtein_distance("a", "") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });            // Expected: 1
    println!("{}", match levenshtein_distance("", "b") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    });            // Expected: 1
    Ok(())
}

