fn inches_to_cm(inches: f64) -> f64 {
    inches * 2.54
}

fn process_input(input_str: &str) -> Result<f64, std::num::ParseFloatError> {
    let inches: f64 = input_str.trim().parse()?;
    Ok(inches)
}

fn convert_and_format(input_str: &str) -> Result<String, Box<dyn std::error::Error>> {
    let inches = process_input(input_str)?;
    let centimeters = inches_to_cm(inches);
    let formatted_output = format!("{:.2} inches is {:.2} cm", inches, centimeters);
    Ok(formatted_output)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let input1 = "1.0";
    let result1 = convert_and_format(input1)?;
