fn is_lowercase(s: &str) -> Result<bool, Box<dyn std::error::Error>> {
    for c in s.chars() {
        if c.is_alphabetic() && !c.is_lowercase() {
            return Ok(false);
        }
    }
    Ok(true)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    assert_eq!(is_lowercase("hello world")?, true);
    assert_eq!(is_lowercase("Hello World")?, false);
    assert_eq!(is_lowercase("123 abc")?, true);
    assert_eq!(is_lowercase("ABC")?, false);
    assert_eq!(is_lowercase("")?, true);
    assert_eq!(is_lowercase("!@#$%")?, true);
    assert_eq!(is_lowercase("aBc")?, false);
    assert_eq!(is_lowercase("a b c D")?, false);
    assert_eq!(is_lowercase("a_b_c")?, true);

    let path = "test_file.txt";
    std::fs::write(path, "lowercase content")?;
    let content = std::fs::read_to_string(path)?;
    assert_eq!(is_lowercase(&content)?, true);
    std::fs::remove_file(path)?;

    std::fs::write(path, "Uppercase Content")?;
    let content = std::fs::read_to_string(path)?;
    assert_eq!(is_lowercase(&content)?, false);
    std::fs::remove_file(path)?;

    Ok(())
}

