use std::io::{self, BufRead};

fn rectangle_diagonal(width: f64, height: f64) -> Result<f64, io::Error> {
    if width.is_nan() || height.is_nan() {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "Inputs cannot be NaN"));
    }
    if width < 0.0 || height < 0.0 {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "Inputs cannot be negative"));
    }

    let width_squared = width.powi(2);
    let height_squared = height.powi(2);
    let sum_of_squares = width_squared + height_squared;
    Ok(sum_of_squares.sqrt())
}

fn main() -> Result<(), io::Error> {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let width_str = lines.next().ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "Missing width input"))??;
    let height_str = lines.next().ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "Missing height input"))??;

    let width: f64 = width_str.trim().parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, format!("Failed to parse width: {}", e)))?;
    let height: f64 = height_str.trim().parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, format!("Failed to parse height: {}", e)))?;

    let diagonal = rectangle_diagonal(width, height)?;
    println!("{}", diagonal);
    Ok(())
}

