fn remove_non_alpha(input: &str) -> String {
    let mut result = String::new();
    for c in input.chars() {
        if c.is_alphabetic() {
            result.push(c);
        }
    }
    result
}

fn process_file(file_path: &str) -> Result<String, std::io::Error> {
    let content = match std::fs::read_to_string(file_path) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let processed_content = remove_non_alpha(&content);
    let temp_file_path = "temp_output.txt";
    match std::fs::write(temp_file_path, &processed_content) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(processed_content)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let test_string = "Hello123World!";
    let cleaned_string = remove_non_alpha(test_string);
    println!("Original: \"{}\", Cleaned: \"{}\"", test_string, cleaned_string);

    let path = "input.txt";
    match std::fs::write(path, "This is a test 123!@#") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let processed_output = match process_file(path) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("Processed file content: {}", processed_output);

    let non_existent_path = "non_existent.txt";
    let _ = match process_file(non_existent_path) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }; // This will propagate an error
    Ok(())
}

