use std::collections::HashMap;

fn find_single_mode(numbers: &Vec<i32>) -> Result<i32, Box<dyn std::error::Error>> {
    let mut counts = HashMap::new();

    for &num in numbers {
        *counts.entry(num).or_insert(0) += 1;
    }

    let mut max_count = 0;
    let mut mode = None;

    for (&num, &count) in &counts {
        if count > max_count {
            max_count = count;
            mode = Some(num);
        }
    }

    mode.ok_or_else(|| "Input vector is empty, no mode found".into())
}

