    use super::*;

    #[test]
    fn test_same_day() -> Result<(), &'static str> {
        assert_eq!(days_between_naive((2023, 1, 1), (2023, 1, 1))?, 0);
        Ok(())
    }

    #[test]
    fn test_different_days_same_month() -> Result<(), &'static str> {
        assert_eq!(days_between_naive((2023, 1, 1), (2023, 1, 10))?, 9);
        Ok(())
    }

    #[test]
    fn test_different_months_same_year() -> Result<(), &'static str> {
        assert_eq!(days_between_naive((2023, 1, 1), (2023, 2, 1))?, 30);
        assert_eq!(days_between_naive((2023, 1, 15), (2023, 2, 15))?, 30);
        assert_eq!(days_between_naive((2023, 1, 30), (2023, 2, 1))?, 1);
        Ok(())
    }

    #[test]
    fn test_different_years() -> Result<(), &'static str> {
        assert_eq!(days_between_naive((2023, 1, 1), (2024, 1, 1))?, 360);
        assert_eq!(days_between_naive((2023, 6, 15), (2024, 6, 15))?, 360);
        Ok(())
    }

