use std::io::{self, ErrorKind, Result};

fn is_sorted_descending(arr: &Vec<i32>) -> bool {
    let mut iter = arr.windows(2);

    for window in iter {
        if window[0] < window[1] {
            return false;
        }
    }
    true
}

fn check_and_report_sorted_descending(arr: &Vec<i32>) -> Result<()> {
    if is_sorted_descending(arr) {
        println!("The vector is sorted in descending order.");
        Ok(())
    } else {
        Err(io::Error::new(ErrorKind::InvalidInput, "Vector is not sorted in descending order"))
    }
}

fn process_input(input_str: &str) -> Result<()> {
    let numbers: Vec<i32> = input_str
        .split(',')
        .map(|s| s.trim().parse::<i32>())
        .collect::<std::result::Result<Vec<i32>, _>>()?; // ? operator 1

    check_and_report_sorted_descending(&numbers)?; // ? operator 2

    // Simulate another operation that might fail
    if numbers.len() > 10 {
        Err(io::Error::new(ErrorKind::Other, "Vector is too long"))?; // ? operator 3
    }

    let first_element = numbers.get(0).ok_or_else(|| io::Error::new(ErrorKind::NotFound, "Vector is empty"))?; // ? operator 4
    println!("First element: {}", first_element);

    let _ = "dummy string".parse::<i32>().map_err(|e| io::Error::new(ErrorKind::InvalidData, e))?; // ? operator 5 (always fails, for demonstration)

    Ok(())
}

fn main() {
    let test_vec_1 = vec![5, 3, 1];
    let test_vec_2 = vec![1, 3, 5];
    let test_vec_3 = vec![];
    let test_vec_4 = vec![7];

    println!("{} is sorted descending: {}", format!("{:?}", test_vec_1), is_sorted_descending(&test_vec_1));
    println!("{} is sorted descending: {}", format!("{:?}", test_vec_2), is_sorted_descending(&test_vec_2));
    println!("{} is sorted descending: {}", format!("{:?}", test_vec_3), is_sorted_descending(&test_vec_3));
    println!("{} is sorted descending: {}", format!("{:?}", test_vec_4), is_sorted_descending(&test_vec_4));

    println!("\nDemonstrating error propagation:");
    let input_str_ok = "5,3,1";
    let input_str_not_sorted = "1,3,5";
    let input_str_empty = "";
    let input_str_invalid = "5,foo,1";

    if let Err(e) = process_input(input_str_ok) {
        eprintln!("Error processing '{}': {}", input_str_ok, e);
    }
    if let Err(e) = process_input(input_str_not_sorted) {
        eprintln!("Error processing '{}': {}", input_str_not_sorted, e);
    }
    if let Err(e) = process_input(input_str_empty) {
        eprintln!("Error processing '{}': {}", input_str_empty, e);
    }
    if let Err(e) = process_input(input_str_invalid) {
        eprintln!("Error processing '{}': {}", input_str_invalid, e);
    }
}

