fn median_of_two_sorted(nums1: &Vec<i32>, nums2: &Vec<i32>) -> io::Result<f64> {
    let mut merged = Vec::new();
    let (mut i, mut j) = (0, 0);

    while i < nums1.len() && j < nums2.len() {
        if nums1[i] < nums2[j] {
            merged.push(nums1[i]);
            i += 1;
        } else {
            merged.push(nums2[j]);
            j += 1;
