fn shift_char(c: char, shift: u8) -> Result<char, std::fmt::Error> {
    if c.is_ascii_lowercase() {
        let first_char_code = b'a';
        let last_char_code = b'z';
        let offset = (c as u8 - first_char_code + shift) % (last_char_code - first_char_code + 1);
        Ok((first_char_code + offset) as char)
    } else {
        Ok(c)
    }
}

fn shift_encode(input: &str, shift: u8) -> Result<String, std::fmt::Error> {
    let mut encoded_chars = Vec::new();
    for c in input.chars() {
        let shifted_c = shift_char(c, shift)?;
        encoded_chars.push(shifted_c);
    }
    Ok(encoded_chars.iter().collect())
}

