fn count_substring(haystack: &str, needle: &str) -> Result<usize, std::io::Error> {
    if needle.is_empty() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Needle cannot be empty",
        ));
    }

    let mut count = 0;
    let mut search_start = 0;

    loop {
        let remaining_haystack = haystack.get(search_start..).ok_or_else(|| {
            std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "Failed to slice haystack string",
            )
        })?;

        if remaining_haystack.is_empty() {
            break;
        }

        if let Some(pos) = remaining_haystack.find(needle) {
            count += 1;
            let new_start = search_start + pos + needle.len();
            search_start = new_start;
        } else {
            break;
        }
    }
    Ok(count)
}

