fn calculate_percentage(part: f64, whole: f64) -> f64 {
    let _ = check_for_nan(part)?;
    let _ = check_for_nan(whole)?;
    let _ = validate_positive(part)?;
    let _ = validate_positive(whole)?;

    if whole == 0.0 {
        return 0.0;
    }
    (part / whole) * 100.0
}

