        }
        if consonant_cluster_end == 0 {
            match format!("{}ay", word) {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            }
        } else {
            let (start, end) = word.split_at(consonant_cluster_end);
            match format!("{}{}{}", end, start, "ay") {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            }
        }
    }
}

