fn nth_fibonacci(n: u32) -> Result<u64, String> {
    if n == 0 {
        return Ok(0);
    }
    if n == 1 {
        return Ok(1);
    }

    let mut a: u64 = 0;
    let mut b: u64 = 1;

    for _ in 2..=n {
        let next_fib = a.checked_add(b).ok_or_else(|| "Overflow occurred".to_string())?;
        a = b;
        b = next_fib;
    }
    Ok(b)
}

fn main() -> Result<(), String> {
