fn total_expenses(expenses: &Vec<(String, f64)>) -> Result<f64, String> {
    let mut total = 0.0;
    for (_desc, amount) in expenses {
        let current_amount = *amount;
        if current_amount < 0.0 {
            return Err("Negative expense amount found".to_string());
        }
        total += current_amount;
    }
    Ok(total)
}

fn main() -> Result<(), String> {
    let expenses1 = vec![("Groceries".to_string(), 50.5), ("Fuel".to_string(), 30.0)];
    let total1 = total_expenses(&expenses1)?;
    println!("Total 1: {}", total1);

    let expenses2 = vec![];
    let total2 = total_expenses(&expenses2)?;
    println!("Total 2: {}", total2);

    let expenses3 = vec![("Rent".to_string(), 1200.0), ("Utilities".to_string(), 150.75)];
    let total3 = total_expenses(&expenses3)?;
    println!("Total 3: {}", total3);

    let expenses4 = vec![("Book".to_string(), 25.0), ("Coffee".to_string(), 4.5)];
    let total4 = total_expenses(&expenses4)?;
    println!("Total 4: {}", total4);

    let expenses5 = vec![("Gift".to_string(), -10.0)];
    if let Err(e) = total_expenses(&expenses5) {
        println!("Error for expenses5: {}", e);
    } else {
        return Err("Negative expense was not caught".to_string());
    }

    Ok(())
}

