fn is_valid_email(email: &str) -> bool {
    let mut parts = email.split('@');
    let _local_part = parts.next()?;
    let domain_part = parts.next()?;
    if parts.next().is_some() {
        return false;
    }
    if email.is_empty() {
        return false;
    }
    if domain_part.is_empty() {
        return false;
    }
    let mut domain_parts = domain_part.split('.');
    let _first_domain_segment = domain_parts.next()?;
    let _second_domain_segment = domain_parts.next()?;
    true
}

