fn find_max(numbers: &Vec<i32>) -> Result<i32, &'static str> {
    let mut max_val = *numbers.get(0).ok_or("Vector is empty")?;

    let mut iter = numbers.iter();
    iter.next(); // Skip the first element, already handled

    for &num in iter {
        if num > max_val {
            max_val = num;
        }
    }
    Ok(max_val)
}

fn main() -> Result<(), &'static str> {
