fn play_rps_round(p1_choice: char, p2_choice: char) -> Result<String, &'static str> {
    let p1_choice_norm = p1_choice.to_ascii_uppercase();
    let p2_choice_norm = p2_choice.to_ascii_uppercase();

    if !['R', 'P', 'S'].contains(&p1_choice_norm) {
        return Err("Invalid choice for Player 1");
    }
    if !['R', 'P', 'S'].contains(&p2_choice_norm) {
        return Err("Invalid choice for Player 2");
    }

    let winner = match (p1_choice_norm, p2_choice_norm) {
        (c1, c2) if c1 == c2 => "Tie",
        ('R', 'S') | ('P', 'R') | ('S', 'P') => "Player 1",
        _ => "Player 2",
    };
    Ok(winner.to_string())
}

fn main() -> Result<(), &'static str> {
    let result1 = match play_rps_round('R', 'S') {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
