    println!("R vs S: {}", result1);

    let result2 = match play_rps_round('P', 'P') {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("P vs P: {}", result2);

    let result3 = match play_rps_round('S', 'R') {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
