fn capitalize_words(s: &str) -> Result<String, std::fmt::Error> {
    let mut result = String::new();
    let mut capitalize_next = true;

    for c in s.chars() {
        if c.is_whitespace() {
            result.write_str(c.to_string().as_str())?;
            capitalize_next = true;
        } else if capitalize_next {
            result.write_str(c.to_uppercase().to_string().as_str())?;
            capitalize_next = false;
        } else {
            result.write_str(c.to_lowercase().to_string().as_str())?;
        }
    }
    Ok(result)
}

