fn fibonacci_sequence(max_val: u64) -> Result<Vec<u64>, Box<dyn std::error::Error>> {
    let mut sequence = Vec::new();
    let mut a = 0u64;
    let mut b = 1u64;

    sequence.push(a);

    if max_val == 0 {
        return Ok(sequence);
    }

    while a <= max_val {
        let temp = a;
        a = b;
        b = temp.checked_add(b).ok_or("Overflow in Fibonacci sequence calculation")?;

        if a > max_val {
            break;
        }
        sequence.push(a);
    }
    Ok(sequence)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let limit1 = 10;
    let seq1 = fibonacci_sequence(limit1)?;
    println!("Fibonacci sequence up to {}: {:?}", limit1, seq1);

    let limit2 = 0;
    let seq2 = fibonacci_sequence(limit2)?;
    println!("Fibonacci sequence up to {}: {:?}", limit2, seq2);

    let limit3 = 1;
    let seq3 = fibonacci_sequence(limit3)?;
    println!("Fibonacci sequence up to {}: {:?}", limit3, seq3);

    let limit4 = u64::MAX;
    let seq4 = fibonacci_sequence(limit4);
    if let Err(e) = seq4 {
        eprintln!("Error generating sequence for {}: {}", limit4, e);
    } else {
        println!("Fibonacci sequence up to {}: {:?}", limit4, seq4?);
    }
    Ok(())
}

