fn reverse_integer(x: i32) -> Result<i32, &'static str> {
    let is_negative = x < 0;
    let mut num = x.checked_abs().ok_or("Failed to get absolute value")?;
    let mut reversed = 0i32;

    while num > 0 {
        let digit = num.checked_rem(10).ok_or("Modulo operation failed")?;
        reversed = reversed.checked_mul(10).ok_or("Multiplication overflow")?;
        reversed = reversed.checked_add(digit).ok_or("Addition overflow")?;
        num = num.checked_div(10).ok_or("Division by zero or overflow")?;
    }

    if is_negative {
        reversed = reversed.checked_mul(-1).ok_or("Negation overflow")?;
    }

    Ok(reversed)
}

fn main() -> Result<(), &'static str> {
    println!("{}", reverse_integer(123)?);
    println!("{}", reverse_integer(-456)?);
    println!("{}", reverse_integer(0)?);
    println!("{}", reverse_integer(100)?);
    println!("{}", reverse_integer(-100)?);
    println!("{}", reverse_integer(2147483647).unwrap_or(-1)); // Should overflow
    println!("{}", reverse_integer(-2147483648).unwrap_or(-1)); // Should overflow
    Ok(())
}

