fn remove_duplicates_sorted(input: &Vec<i32>) -> Result<Vec<i32>, &'static str> {
    let mut result = Vec::new();
    let mut iter = input.iter();

    if let Some(&first) = iter.next() {
        result.push(first);
    } else {
        return Ok(result); 
    }

    for &num in iter {
        if let Some(&last_added) = result.last() {
            if num != last_added {
                result.push(num);
            }
        } else {
            return Err("Unexpected empty result vector after first element"); 
        }
    }
    Ok(result)
}

