        Ok(())
    }

    #[test]
    fn test_no_duplicates() -> Result<(), &'static str> {
        let input = vec![1, 2, 3, 4];
        let expected = vec![1, 2, 3, 4];
        assert_eq!(remove_duplicates_sorted(&input)?, expected);
        Ok(())
    }

