fn manhattan_distance_2d(x1: i32, y1: i32, x2: i32, y2: i32) -> Result<i32, Box<dyn std::error::Error>> {
    let dx = x1.checked_sub(x2).ok_or("subtraction overflow for x coordinates")?;
    let dy = y1.checked_sub(y2).ok_or("subtraction overflow for y coordinates")?;

    let abs_dx = dx.checked_abs().ok_or("absolute value overflow for dx")?;
    let abs_dy = dy.checked_abs().ok_or("absolute value overflow for dy")?;

    let distance = abs_dx.checked_add(abs_dy).ok_or("addition overflow for distance")?;
    Ok(distance)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_manhattan_distance_examples() -> Result<(), Box<dyn std::error::Error>> {
        assert_eq!(manhattan_distance_2d(0, 0, 3, 4)?, 7);
        assert_eq!(manhattan_distance_2d(1, 1, 1, 5)?, 4);
        Ok(())
    }

    #[test]
    fn test_negative_coordinates() -> Result<(), Box<dyn std::error::Error>> {
        assert_eq!(manhattan_distance_2d(-1, -1, -5, -5)?, 8);
        Ok(())
    }

    #[test]
    fn test_mixed_coordinates() -> Result<(), Box<dyn std::error::Error>> {
        assert_eq!(manhattan_distance_2d(-1, 0, 2, 3)?, 6);
        Ok(())
    }

    #[test]
    fn test_zero_distance() -> Result<(), Box<dyn std::error::Error>> {
        assert_eq!(manhattan_distance_2d(5, 5, 5, 5)?, 0);
        Ok(())
    }

    #[test]
    fn test_large_values_no_overflow() -> Result<(), Box<dyn std::error::Error>> {
        let x1 = 1_000_000_000;
        let y1 = 1_000_000_000;
        let x2 = 500_000_000;
        let y2 = 500_000_000;
        let expected = 1_000_000_000;
        assert_eq!(manhattan_distance_2d(x1, y1, x2, y2)?, expected);
        Ok(())
    }

    #[test]
    fn test_overflow_x() {
        let x1 = i32::MAX;
        let x2 = i32::MIN;
        let result = manhattan_distance_2d(x1, 0, x2, 0);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err().to_string(), "subtraction overflow for x coordinates");
    }

    #[test]
    fn test_overflow_abs_dx() {
        let x1 = i32::MIN;
        let x2 = 0;
        // x1 - x2 = i32::MIN. abs(i32::MIN) overflows for i32.
        let result = manhattan_distance_2d(x1, 0, x2, 0);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err().to_string(), "absolute value overflow for dx");
    }

    #[test]
    fn test_overflow_add() {
        let x1 = i32::MAX / 2;
        let y1 = i32::MAX / 2;
        let x2 = 0;
        let y2 = 0;
        // dx = i32::MAX / 2, dy = i32::MAX / 2. Their sum overflows.
        let result = manhattan_distance_2d(x1, y1, x2, y2);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err().to_string(), "addition overflow for distance");
    }
}

